"""A self-contained search-and-replace command.

All matching, traversal, preview rendering and file updates are implemented here.
The small native entry point only supplies this program to the Python runtime.
"""
import curses
import errno
import fnmatch
import functools
import os
import pwd
import re
import stat
import sys
import tempfile
import termios
import time
import unicodedata

VERSION = 'ambr 0.6.0\n'
FLAGS = [
    ('key-from-file', 'Use file contents of KEYWORD as keyword for search'),
    ('rep-from-file', 'Use file contents of REPLACEMENT as keyword for replacement'),
    ('verbose', 'Verbose message'),
    ('regex', 'Enable regular expression search'),
    ('column', 'Enable column output'),
    ('row', 'Enable row output'),
    ('binary', 'Enable binary file search'),
    ('statistics', 'Enable statistics output'),
    ('skipped', 'Enable skipped file output'),
    ('preserve-time', 'Enable timestamp preserve'),
    ('no-interactive', 'Disable interactive replace'),
    ('no-recursive', 'Disable recursive directory search'),
    ('no-symlink', 'Disable symbolic link follow'),
    ('no-color', 'Disable colored output'),
    ('no-file', 'Disable filename output'),
    ('no-skip-vcs', 'Disable vcs directory ( .hg/.git/.svn ) skip'),
    ('no-skip-gitignore', 'Disable .gitignore skip'),
    ('no-fixed-order', 'Disable output order guarantee'),
    ('no-parent-ignore', 'Disable .*ignore file search at parent directories'),
    ('tbm', '[Experimental] Enable TBM matcher'),
    ('sse', '[Experimental] Enable SSE 4.2'),
    ('help', 'Prints help information'),
    ('version', 'Prints version information'),
]
NUMERIC = {
    'max-threads': ('NUM', 10, 'Number of max threads'),
    'size-per-thread': ('BYTES', 1048576, 'File size per one thread'),
    'bin-check-bytes': ('BYTES', 256, 'Read size for checking binary'),
    'mmap-bytes': ('BYTES', 1048576, '[Experimental] Minimum size for using mmap'),
}
FLAG_NAMES = {x[0] for x in FLAGS}
SHORT = {'r': 'regex', 'h': 'help', 'V': 'version'}
DEFAULTS = {
    'regex': False, 'column': False, 'row': False, 'binary': False,
    'statistics': False, 'skipped': False, 'interactive': True,
    'recursive': True, 'symlink': True, 'color': True, 'file': True,
    'skip_vcs': True, 'skip_gitignore': True, 'fixed_order': True,
    'parent_ignore': True, 'line_by_match': False,
}
PROMPT = b'Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: '


def emit(stream, value):
    if isinstance(value, str):
        value = value.encode('utf-8', 'replace')
    stream.write(value)
    stream.flush()


def help_message(name):
    result = VERSION + '\nUSAGE:\n    ' + name
    result += ' [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...\n\nFLAGS:\n'
    for flag, description in FLAGS:
        short = next((k for k, v in SHORT.items() if v == flag), None)
        left = ('    -' + short + ', ' if short else '        ') + '--' + flag
        result += left.ljust(30) + description + '\n'
    result += '\nOPTIONS:\n'
    for option, (param, default, description) in NUMERIC.items():
        left = '        --' + option + ' <' + param + '>'
        result += left.ljust(36) + description + ' [default: ' + str(default) + ']\n'
    result += ('\nARGS:\n    <KEYWORD>        Keyword for search\n'
               '    <REPLACEMENT>    Keyword for replace\n'
               '    <PATHS>...       Search paths\n')
    return result


def argument_label(key):
    return '--' + key + (' <' + NUMERIC[key][0] + '>' if key in NUMERIC else '')


def usage(name, selected=None, defaults=False):
    selected = set(selected or ())
    if defaults:
        selected.update(NUMERIC)
    if not selected:
        return name + ' [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...'
    return name + ' <KEYWORD> <REPLACEMENT> ' + ' '.join(argument_label(k) for k in sorted(selected))


class CommandExit(Exception):
    def __init__(self, code):
        self.code = code


def cli_error(message, used=None, name='executable', defaults=False):
    text = 'error: ' + message
    if used is not None:
        text += '\n\nUSAGE:\n    ' + usage(name, used, defaults)
        text += '\n\nFor more information try --help'
    emit(sys.stderr.buffer, text + '\n')
    raise CommandExit(1)


def jaro_winkler(a, b):
    """Similarity is used only for spelling hints, never option abbreviation."""
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    window = max(len(a), len(b)) // 2 - 1
    am = [False] * len(a)
    bm = [False] * len(b)
    count = 0
    for i, char in enumerate(a):
        for j in range(max(0, i - window), min(i + window + 1, len(b))):
            if not bm[j] and char == b[j]:
                am[i] = bm[j] = True
                count += 1
                break
    if not count:
        return 0.0
    aa = [c for i, c in enumerate(a) if am[i]]
    bb = [c for i, c in enumerate(b) if bm[i]]
    trans = sum(c != d for c, d in zip(aa, bb)) / 2
    score = (count / len(a) + count / len(b) + (count - trans) / count) / 3
    prefix = 0
    for x, y in zip(a[:4], b[:4]):
        if x != y:
            break
        prefix += 1
    return score + prefix * 0.1 * (1 - score)


def parse_arguments(argv):
    name = os.path.basename(argv[0]) or 'executable'
    seen = []
    values = {}
    positional = []
    literal = False

    def unexpected(token):
        selected = set(seen)
        message = "Found argument '" + token + "' which wasn't expected, or isn't valid in this context"
        if token.startswith('--'):
            candidate, score = None, 0.8
            for known in list(NUMERIC) + [k for k, _ in FLAGS]:
                similarity = jaro_winkler(token[2:], known)
                if similarity > score:
                    candidate, score = known, similarity
            if candidate:
                message += '\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m' + candidate + '\x1b[0m?'
                selected.add(candidate)
        cli_error(message, selected, name)

    def add_flag(key):
        if key == 'help':
            emit(sys.stdout.buffer, help_message(name))
            raise CommandExit(0)
        if key == 'version':
            emit(sys.stdout.buffer, VERSION)
            raise CommandExit(0)
        seen.append(key)
        values[key] = True

    i = 1
    while i < len(argv):
        arg = argv[i]
        if literal:
            positional.append(arg)
        elif arg == '--':
            literal = True
        elif arg.startswith('--'):
            key, eq, value = arg[2:].partition('=')
            if key in FLAG_NAMES:
                add_flag(key)
            elif key in NUMERIC:
                seen.append(key)
                if not eq:
                    if i + 1 < len(argv) and (not argv[i + 1].startswith('-') or argv[i + 1] == '-'):
                        i += 1
                        value = argv[i]
                    else:
                        value = str(NUMERIC[key][1])
                values[key] = value
            else:
                unexpected('--' + key)
        elif arg.startswith('-') and len(arg) > 1:
            for char in arg[1:]:
                if char not in SHORT:
                    unexpected('-' + char)
                add_flag(SHORT[char])
        else:
            positional.append(arg)
        i += 1

    for key in seen:
        if seen.count(key) > 1:
            cli_error("The argument '" + argument_label(key) + "' was provided more than once, but cannot be used multiple times", seen, name, True)
    if len(positional) < 2:
        required = ['<KEYWORD>', '<REPLACEMENT>'][len(positional):]
        cli_error('The following required arguments were not provided:\n' + '\n'.join('    ' + k for k in required), seen, name, True)
    for key, (_, default, _) in NUMERIC.items():
        value = values.get(key, str(default))
        reason = None
        if not value:
            reason = 'cannot parse integer from empty string'
        elif not re.fullmatch(r'\+?[0-9]+', value):
            reason = 'invalid digit found in string'
        elif int(value) > (1 << 64) - 1:
            reason = 'number too large to fit in target type'
        if reason:
            cli_error("Invalid value for '" + argument_label(key) + "': " + reason)
        values[key] = int(value)
    return values, positional[:2], positional[2:] or ['.']


def config_path():
    home = os.environ.get('HOME')
    if home is None:
        try:
            home = pwd.getpwuid(os.getuid()).pw_dir
        except KeyError:
            home = ''
    old = os.path.join(home, '.ambr.toml')
    if os.path.exists(old):
        return old
    base = os.environ.get('XDG_CONFIG_HOME')
    if not base or not os.path.isabs(base):
        base = os.path.join(home, '.config')
    modern = os.path.join(base, 'amber', 'ambr.toml')
    return modern if os.path.exists(modern) else '/etc/amber/ambr.toml'


def strip_comment(line):
    quote = None
    escaped = False
    for i, char in enumerate(line):
        if escaped:
            escaped = False
        elif quote == '"' and char == '\\':
            escaped = True
        elif quote:
            if char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char == '#':
            return line[:i]
    return line


def load_config():
    settings = dict(DEFAULTS)
    try:
        text = open(config_path(), 'r', encoding='utf-8').read()
        data = {}
        table = ''
        keys = set()
        bracket_depth = 0
        for original in text.splitlines():
            line = strip_comment(original).strip()
            if not line:
                continue
            if bracket_depth:
                bracket_depth += line.count('[') - line.count(']')
                continue
            if line.startswith('[') and line.endswith(']'):
                table = line
                continue
            if '=' not in line:
                raise ValueError('not an assignment')
            key, value = (x.strip() for x in line.split('=', 1))
            if key[:1] in ['"', "'"] and key[-1:] == key[:1]:
                key = key[1:-1]
            elif not re.fullmatch(r'[A-Za-z0-9_.-]+', key):
                raise ValueError('bad key')
            if (table, key) in keys:
                raise ValueError('duplicate key')
            keys.add((table, key))
            if not value:
                raise ValueError('missing value')
            if table == '' and key in DEFAULTS:
                if value not in ('true', 'false'):
                    raise ValueError('expected boolean')
                data[key] = value == 'true'
            elif value not in ('true', 'false'):
                if value[:1] not in ['"', "'", '[', '{'] and not re.match(r'^[+\-0-9]|^(?:inf|nan)$', value):
                    raise ValueError('bad value')
                if value.startswith('['):
                    bracket_depth = value.count('[') - value.count(']')
        if bracket_depth:
            raise ValueError('unterminated array')
        settings.update(data)
    except (OSError, UnicodeError, ValueError):
        pass
    return settings


class TerminalFailure(Exception):
    pass


class Console:
    def __init__(self, color):
        term = os.environ.get('TERM')
        if not term:
            raise TerminalFailure()
        try:
            curses.setupterm(term=term)
        except curses.error:
            raise TerminalFailure()
        self.color = color
        self.current = [None, None]
        self.streams = [sys.stdout.buffer, sys.stderr.buffer]
        self.reset_sequence = curses.tigetstr('sgr0')
        self.color_sequence = curses.tigetstr('setaf')
        self.old_color = False
        if not self.color_sequence:
            self.color_sequence = curses.tigetstr('setf')
            self.old_color = True
        self.colors = curses.tigetnum('colors')

    def write(self, value, which=0):
        emit(self.streams[which], value)

    def set_color(self, number, which=0):
        if not self.color or self.current[which] == number:
            return
        if not self.color_sequence or self.colors <= number:
            raise TerminalFailure()
        color = number
        if self.old_color:
            color = (0, 4, 2, 6, 1, 5, 3, 7)[number]
        value = curses.tparm(self.color_sequence, color)
        self.write(re.sub(rb'\$<[^>]*>', b'', value), which)
        self.current[which] = number

    def log(self, message, error=False):
        self.set_color(1 if error else 6, 1)
        self.write(message, 1)

    def reset(self):
        for which in (0, 1):
            if not self.reset_sequence:
                raise TerminalFailure()
            self.write(re.sub(rb'\$<[^>]*>', b'', self.reset_sequence), which)
            self.current[which] = None

    @staticmethod
    def width(text):
        result = 0
        for char in text:
            category = unicodedata.category(char)
            if category in ('Mn', 'Me', 'Cf'):
                continue
            result += 2 if unicodedata.east_asian_width(char) in ('W', 'F') else 1
        return result

    @staticmethod
    def lossy(data):
        return data.decode('utf-8', 'replace').encode('utf-8')

    def preview(self, path, data, start, end, replacement, settings):
        line = data.count(b'\n', 0, start) + 1
        last_lf = data.rfind(b'\n', 0, start)
        row = start - max(0, last_lf)
        label = ''
        width = 0
        if settings['file']:
            shown = os.fsencode(path).decode('utf-8', 'replace')
            self.set_color(2)
            self.write(shown)
            width += self.width(shown)
            label = ': '
        if settings['column']:
            label += str(line) + ':'
        if settings['row']:
            label += str(row) + ':'
        width += len(label)
        pad = max(0, 4 - width)
        width += pad
        self.set_color(6)
        self.write(label + ' ' * pad)
        before_lf = data.rfind(b'\n', 0, min(len(data), start + 1))
        before_cr = data.rfind(b'\r', 0, min(len(data), start + 1))
        beginning = max(before_lf, before_cr)
        beginning = beginning + 1 if beginning > 0 else 0
        prefix = data[beginning:start] if beginning < start else b''
        endings = [i for i in (data.find(b'\n', end), data.find(b'\r', end)) if i >= 0]
        ending = min(endings) if endings else len(data)
        suffix = data[end:ending]

        def body(middle):
            if prefix:
                self.set_color(7)
                self.write(self.lossy(prefix))
            self.set_color(3)
            self.write(self.lossy(middle))
            self.set_color(7)
            self.write(self.lossy(suffix) + b'\n')

        body(data[start:end])
        self.set_color(6)
        self.write(' ' * (width - 3) + '-> ')
        body(replacement)

    @staticmethod
    def get_key():
        old = None
        try:
            if os.isatty(0):
                old = termios.tcgetattr(0)
                raw = termios.tcgetattr(0)
                raw[3] &= ~(termios.ECHO | termios.ICANON | termios.ISIG)
                raw[6][termios.VMIN] = 1
                raw[6][termios.VTIME] = 0
                termios.tcsetattr(0, termios.TCSANOW, raw)
            while True:
                char = os.read(0, 1)
                if char != b'\x1b':
                    return char[0] if char else 0
                char = os.read(0, 1)
                if char in (b'[', b'O'):
                    while True:
                        char = os.read(0, 1)
                        if not char or 64 <= char[0] <= 126:
                            break
        finally:
            if old is not None:
                termios.tcsetattr(0, termios.TCSANOW, old)

    def ask(self):
        while True:
            self.set_color(6)
            self.write(PROMPT)
            char = self.get_key()
            self.write('\n' if char == 10 else chr(char) + '\n')
            if char in (ord('y'), ord('Y'), 10, 13, 32):
                return 'y'
            if char in (ord('n'), ord('N')):
                return 'n'
            if char in (ord('a'), ord('A')):
                return 'a'
            if char in (ord('q'), ord('Q')):
                return 'q'
            if char == 0:
                time.sleep(0.001)


def debug_path(path):
    text = os.fsencode(path).decode('utf-8', 'replace')
    result = '"'
    for char in text:
        result += {'\\': '\\\\', '"': '\\"', '\n': '\\n', '\r': '\\r', '\t': '\\t', '\0': '\\0'}.get(char, char if char.isprintable() else '\\u{' + format(ord(char), 'x') + '}')
    return result + '"'


def os_error(error):
    code = error.errno or errno.EIO
    return os.strerror(code) + ' (os error ' + str(code) + ')'
