def jaro_winkler(a, b):
    """Similarity is used only for spelling hints, never option abbreviation."""
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    window = max(len(a), len(b)) // 2 - 1
    am = [False] * len(a)
    bm = [False] * len(b)
    count = 0
    for i, char in enumerate(a):
        for j in range(max(0, i - window), min(i + window + 1, len(b))):
            if not bm[j] and char == b[j]:
                am[i] = bm[j] = True
                count += 1
                break
    if not count:
        return 0.0
    aa = [c for i, c in enumerate(a) if am[i]]
    bb = [c for i, c in enumerate(b) if bm[i]]
    trans = sum(c != d for c, d in zip(aa, bb)) / 2
    score = (count / len(a) + count / len(b) + (count - trans) / count) / 3
    prefix = 0
    for x, y in zip(a[:4], b[:4]):
        if x != y:
            break
        prefix += 1
    return score + prefix * 0.1 * (1 - score)


def parse_arguments(argv):
    name = os.path.basename(argv[0]) or 'executable'
    seen = []
    values = {}
    positional = []
    literal = False

    def unexpected(token):
        selected = set(seen)
        message = "Found argument '" + token + "' which wasn't expected, or isn't valid in this context"
        if token.startswith('--'):
            candidate, score = None, 0.8
            for known in list(NUMERIC) + [k for k, _ in FLAGS]:
                similarity = jaro_winkler(token[2:], known)
                if similarity > score:
                    candidate, score = known, similarity
            if candidate:
                message += '\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m' + candidate + '\x1b[0m?'
                selected.add(candidate)
        cli_error(message, selected, name)

    def add_flag(key):
        if key == 'help':
            emit(sys.stdout.buffer, help_message(name))
            raise CommandExit(0)
        if key == 'version':
            emit(sys.stdout.buffer, VERSION)
            raise CommandExit(0)
        seen.append(key)
        values[key] = True

    i = 1
    while i < len(argv):
        arg = argv[i]
        if literal:
            positional.append(arg)
        elif arg == '--':
            literal = True
        elif arg.startswith('--'):
            key, eq, value = arg[2:].partition('=')
            if key in FLAG_NAMES:
                add_flag(key)
            elif key in NUMERIC:
                seen.append(key)
                if not eq:
                    if i + 1 < len(argv) and (not argv[i + 1].startswith('-') or argv[i + 1] == '-'):
                        i += 1
                        value = argv[i]
                    else:
                        value = str(NUMERIC[key][1])
                values[key] = value
            else:
                unexpected('--' + key)
        elif arg.startswith('-') and len(arg) > 1:
            for char in arg[1:]:
                if char not in SHORT:
                    unexpected('-' + char)
                add_flag(SHORT[char])
        else:
            positional.append(arg)
        i += 1

    for key in seen:
        if seen.count(key) > 1:
            cli_error("The argument '" + argument_label(key) + "' was provided more than once, but cannot be used multiple times", seen, name, True)
    if len(positional) < 2:
        required = ['<KEYWORD>', '<REPLACEMENT>'][len(positional):]
        cli_error('The following required arguments were not provided:\n' + '\n'.join('    ' + k for k in required), seen, name, True)
    for key, (_, default, _) in NUMERIC.items():
        value = values.get(key, str(default))
        reason = None
        if not value:
            reason = 'cannot parse integer from empty string'
        elif not re.fullmatch(r'\+?[0-9]+', value):
            reason = 'invalid digit found in string'
        elif int(value) > (1 << 64) - 1:
            reason = 'number too large to fit in target type'
        if reason:
            cli_error("Invalid value for '" + argument_label(key) + "': " + reason)
        values[key] = int(value)
