def config_path():
    home = os.environ.get('HOME')
    if home is None:
        try:
            home = pwd.getpwuid(os.getuid()).pw_dir
        except KeyError:
            home = ''
    old = os.path.join(home, '.ambr.toml')
    if os.path.exists(old):
