def strip_comment(line):
    quote = None
    escaped = False
    for i, char in enumerate(line):
        if escaped:
            escaped = False
        elif quote == '"' and char == '\\':
            escaped = True
        elif quote:
            if char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char == '#':
            return line[:i]
    return line


def load_config():
    settings = dict(DEFAULTS)
    try:
        text = open(config_path(), 'r', encoding='utf-8').read()
        data = {}
        table = ''
        keys = set()
        bracket_depth = 0
        for original in text.splitlines():
            line = strip_comment(original).strip()
            if not line:
                continue
            if bracket_depth:
                bracket_depth += line.count('[') - line.count(']')
                continue
            if line.startswith('[') and line.endswith(']'):
                table = line
                continue
            if '=' not in line:
                raise ValueError('not an assignment')
            key, value = (x.strip() for x in line.split('=', 1))
            if key[:1] in ['"', "'"] and key[-1:] == key[:1]:
                key = key[1:-1]
            elif not re.fullmatch(r'[A-Za-z0-9_.-]+', key):
                raise ValueError('bad key')
            if (table, key) in keys:
                raise ValueError('duplicate key')
            keys.add((table, key))
            if not value:
                raise ValueError('missing value')
            if table == '' and key in DEFAULTS:
                if value not in ('true', 'false'):
                    raise ValueError('expected boolean')
                data[key] = value == 'true'
            elif value not in ('true', 'false'):
                if value[:1] not in ['"', "'", '[', '{'] and not re.match(r'^[+\-0-9]|^(?:inf|nan)$', value):
                    raise ValueError('bad value')
                if value.startswith('['):
                    bracket_depth = value.count('[') - value.count(']')
        if bracket_depth:
            raise ValueError('unterminated array')
        settings.update(data)
    except (OSError, UnicodeError, ValueError):
        pass
    return settings


