        'letter': 'l', 'mark': 'm', 'number': 'n', 'punctuation': 'p',
        'symbol': 's', 'separator': 'z', 'other': 'c',
        'uppercaseletter': 'lu', 'lowercaseletter': 'll', 'titlecaseletter': 'lt',
        'modifierletter': 'lm', 'otherletter': 'lo', 'nonspacingmark': 'mn',
        'spacingmark': 'mc', 'enclosingmark': 'me', 'decimalnumber': 'nd',
        'decimaldigitnumber': 'nd', 'letternumber': 'nl', 'othernumber': 'no',
        'space': 'whitespace', 'space_separator': 'zs', 'spaceseparator': 'zs',
        'connectorpunctuation': 'pc', 'dashpunctuation': 'pd',
        'openpunctuation': 'ps', 'closepunctuation': 'pe',
        'initialpunctuation': 'pi', 'finalpunctuation': 'pf',
        'otherpunctuation': 'po', 'mathsymbol': 'sm', 'currencysymbol': 'sc',
        'modifiersymbol': 'sk', 'othersymbol': 'so', 'control': 'cc',
        'format': 'cf', 'surrogate': 'cs', 'privateuse': 'co', 'unassigned': 'cn',
