        if name == 'lowercase':
            return char.islower()
        if name == 'uppercase':
            return char.isupper()
        if name == 'numeric':
            return char.isnumeric()
        if name == 'ascii':
            return point < 128
        if name == 'any':
            return not 0xd800 <= point <= 0xdfff
        if name == 'assigned':
            return cat != 'cn'
        if name == 'joincontrol':
            return point in (0x200c, 0x200d)
        if name == 'asciihexdigit':
