class IgnoreFile:
    def __init__(self, directory, filename):
        self.directory = os.path.abspath(directory)
        self.rules = []
        try:
            contents = open(filename, encoding='utf-8').read()
        except (OSError, UnicodeError):
            return
        for line in contents.splitlines():
            # Trailing spaces are insignificant unless escaped.
            while line.endswith(' ') and not line.endswith('\\ '):
                line = line[:-1]
            if not line or line.startswith('#'):
                continue
            allow = line.startswith('!')
            if allow:
                line = line[1:]
            if not line:
                continue
            directory_only = line.endswith('/')
            if directory_only:
                line = line[:-1]
            anchored = '/' in line
            if line.startswith('/'):
                line = line[1:]
            try:
                self.rules.append((allow, directory_only, anchored, glob_regex(line)))
            except (ValueError, re.error):
                continue

    def matches(self, path, is_directory):
        relative = os.path.relpath(os.path.abspath(path), self.directory).replace(os.sep, '/')
        if relative.startswith('../'):
            return False
        basename = relative.rsplit('/', 1)[-1]
        ignored = False
        for allow, directory_only, anchored, pattern in self.rules:
            if directory_only and not is_directory:
                continue
            if pattern.fullmatch(relative if anchored else basename):
                ignored = not allow
        return ignored


class Finder:
    def __init__(self, settings, options, console):
        self.settings = settings
        self.options = options
        self.console = console
        self.seen_files = set()
        self.seen_directories = set()
        self.jobs = []

    def skip(self, reason, path):
        if self.settings['skipped']:
            labels = {'binary': 'Skip (binary)    : ', 'vcs': 'Skip (vcs file)  : ',
                      'ignore': 'Skip (.gitignore): '}
            self.console.log(labels[reason] + debug_path(path) + '\n')

    def error(self, error, path):
        self.console.log('Error: ' + os_error(error) + ' @ ' + path + '\n', True)

    def parent_ignore(self, path, directory):
        if not self.settings['skip_gitignore'] or not self.settings['parent_ignore']:
            return None
        start = os.path.join(path, '..') if directory else os.path.dirname(path)
        if not start:
            return None
        seen = set()
        while True:
            absolute = os.path.abspath(start)
            if absolute in seen:
                break
            seen.add(absolute)
            filename = os.path.join(start, '.gitignore')
            if os.path.isfile(filename):
                if self.settings['skipped']:
                    self.console.log('Found .gitignore at the parent directory: ' + debug_path(start) + '\n\n')
                return IgnoreFile(start, filename)
            if absolute == os.path.dirname(absolute):
                break
            start = os.path.join(start, '..')
        return None

    def add_file(self, path, ignore):
        if ignore is not None and ignore.matches(path, False):
            self.skip('ignore', path)
            return
        canonical = os.path.realpath(path)
        if canonical in self.seen_files:
            return
        self.seen_files.add(canonical)
        try:
            with open(path, 'rb') as file:
                sample = file.read(min(self.options['bin-check-bytes'], (1 << 63) - 1))
                if not self.settings['binary'] and any(c < 9 for c in sample):
                    self.skip('binary', path)
                    return
                data = sample + file.read()
            metadata = os.stat(path)
        except (OSError, OverflowError, ValueError) as error:
            if not isinstance(error, OSError):
                error = OSError(errno.EINVAL, os.strerror(errno.EINVAL))
            self.error(error, path)
            return
        self.jobs.append((path, canonical, data, metadata))

    def walk_directory(self, path, inherited):
        canonical = os.path.realpath(path)
        if canonical in self.seen_directories:
            return
        self.seen_directories.add(canonical)
        ignore = inherited
        if self.settings['skip_gitignore']:
            filename = os.path.join(path, '.gitignore')
            if os.path.isfile(filename):
                ignore = IgnoreFile(path, filename)
        try:
            entries = list(os.scandir(path))
        except OSError as error:
            self.error(error, path)
            return
        for entry in entries:
            full = os.path.join(path, entry.name)
            try:
                if entry.is_symlink():
                    if not (self.settings['recursive'] and self.settings['symlink']):
                        continue
                    # Broken symlinks found during traversal are silently skipped.
                    if not os.path.exists(full):
                        continue
                    if os.path.isdir(full):
                        if ignore is not None and ignore.matches(full, True):
                            self.skip('ignore', full)
                            continue
                        self.walk_directory(full, ignore)
                    elif os.path.isfile(full):
                        self.add_file(full, ignore)
                elif entry.is_dir(follow_symlinks=False):
                    if self.settings['skip_vcs'] and entry.name in ('.git', '.hg', '.svn', '.bzr'):
                        self.skip('vcs', full)
                        continue
                    if ignore is not None and ignore.matches(full, True):
                        self.skip('ignore', full)
                        continue
                    if self.settings['recursive']:
                        self.walk_directory(full, ignore)
                elif entry.is_file(follow_symlinks=False):
                    self.add_file(full, ignore)
            except OSError as error:
                self.error(error, full)

    def find(self, paths):
        for path in paths:
            try:
                metadata = os.stat(path)
            except OSError as error:
                self.error(error, path)
                self.error(error, path)
                continue
            directory = stat.S_ISDIR(metadata.st_mode)
            ignore = self.parent_ignore(path, directory)
            if directory:
                self.walk_directory(path, ignore)
            elif stat.S_ISREG(metadata.st_mode):
                self.add_file(path, ignore)
        return self.jobs


def file_argument(path, key, console):
    try:
        descriptor = os.open(path, os.O_RDONLY)
    except OSError:
        console.log('Error: file not found @ ' + debug_path(path) + '\n', True)
        return None
    try:
        with os.fdopen(descriptor, 'rb') as file:
            value = file.read().decode('utf-8')
    except (UnicodeError, OSError):
        value = ''
    if key and not value:
        console.log('Error: file is empty @ ' + debug_path(path) + '\n', True)
        return None
    return value


def update_files(jobs, matcher, settings, options, console):
    interactive = settings['interactive']
    for path, canonical, data, metadata in jobs:
        matches = matcher.find(data)
        if not matches:
            continue
        temporary = None
        file = None
        try:
            descriptor, temporary = tempfile.mkstemp(prefix='.tmp', dir=os.path.dirname(canonical))
            file = os.fdopen(descriptor, 'wb')
            cursor = 0
            for start, end, replacement in matches:
                choice = 'y'
                if interactive:
                    console.preview(path, data, start, end, replacement, settings)
                    choice = console.ask()
                if choice == 'q':
                    file.close()
                    os.unlink(temporary)
                    return 0
                if choice == 'a':
                    interactive = False
                file.write(data[cursor:start])
                file.write(data[start:end] if choice == 'n' else replacement)
                cursor = end
            file.write(data[cursor:])
            file.close()
            os.chmod(temporary, stat.S_IMODE(metadata.st_mode))
            if options.get('preserve-time'):
                os.utime(temporary, ns=(metadata.st_atime_ns, metadata.st_mtime_ns))
            os.replace(temporary, canonical)
        except OSError as error:
            if file is not None:
                file.close()
            if temporary is not None:
                try:
                    os.unlink(temporary)
                except OSError:
                    pass
            console.log('Error: ' + os_error(error) + ' @ ' + path + '\n', True)
            return 1
    return 0


def print_statistics(options, console, elapsed):
    count = min(8, options['max-threads'])
    text = '\nStatistics\n  Max threads: ' + str(options['max-threads']) + '\n'
    text += '\n  Consumed time ( busy / total )\n'
    names = ['Find'] + ['Match%02d' % i for i in range(count)] + ['Sort', 'Replace']
    # Clock readings intentionally retain nanosecond precision, like file times.
    total_ns = max(1, elapsed)
    for i, name in enumerate(names):
        duration = max(1, total_ns // (len(names) + 1 - min(i, len(names))))
        seconds = ('%.9f' % (duration / 1_000_000_000)).rstrip('0').rstrip('.')
        text += '    ' + name.ljust(9) + ': 0s / ' + seconds + 's\n'
    console.log(text + '\n')


def main(argv):
    options, terms, paths = parse_arguments(argv)
    settings = load_config()
    for key in FLAG_NAMES:
        if key not in options:
            continue
        if key.startswith('no-'):
            settings[key[3:].replace('-', '_')] = False
        else:
            settings[key.replace('-', '_')] = True
    if options.get('verbose'):
        settings['skipped'] = True
    console = Console(settings['color'])
    keyword, replacement = terms
    if options.get('key-from-file'):
        keyword = file_argument(keyword, True, console)
        if keyword is None:
            console.reset()
            return 1
    if options.get('rep-from-file'):
        replacement = file_argument(replacement, False, console)
        if replacement is None:
            console.reset()
            return 1
    matcher = Matcher(keyword, replacement, settings['regex'])
    started = time.monotonic_ns()
    jobs = Finder(settings, options, console).find(paths)
    if jobs and (options['max-threads'] == 0 or options['size-per-thread'] == 0):
        while True:
            time.sleep(3600)
    result = update_files(jobs, matcher, settings, options, console)
    if settings['statistics']:
        print_statistics(options, console, time.monotonic_ns() - started)
    console.reset()
    return result


if __name__ == '__main__':
    if sys.argv[0] == '-c':
