def glob_regex(pattern):
    """Path-aware globbing; unlike fnmatch, one star cannot cross a slash."""
    result = ''
    i = 0
    while i < len(pattern):
        char = pattern[i]
        if char == '*':
            end = i + 1
            while end < len(pattern) and pattern[end] == '*':
                end += 1
            if end - i >= 2:
                if end < len(pattern) and pattern[end] == '/' and (i == 0 or pattern[i - 1] == '/'):
                    result += '(?:.*/)?'
                    end += 1
                else:
                    result += '.*'
            else:
                result += '[^/]*'
            i = end
            continue
        if char == '?':
            result += '[^/]'
        elif char == '[':
            end = i + 1
            if end < len(pattern) and pattern[end] in '^!':
                end += 1
            if end < len(pattern) and pattern[end] == ']':
                end += 1
            end = pattern.find(']', end)
            if end < 0:
                raise ValueError('invalid glob')
            content = pattern[i + 1:end]
            if content.startswith('!'):
                content = '^' + content[1:]
            result += '[' + content + ']'
            i = end
        elif char == '\\':
            i += 1
            if i >= len(pattern):
                raise ValueError('invalid glob')
            result += re.escape(pattern[i])
        else:
            result += re.escape(char)
        i += 1
    return re.compile('^' + result + '$')


